export interface Customer {
  yearsWithMHPCO: number;
  contractCount: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,

input.newString:
const basePremiumForItem = (item: Item): number =>
  BASE_PREMIUM_BY_TYPE[item.type];

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const basePremiumForGroup = (group: Item[]): number => {
  if (group.length === RUNE_BLOCK_SIZE) {
    return RUNE_BLOCK_PREMIUM;
  }
  return group.reduce((sum, item) => sum + basePremiumForItem(item), 0);
};

export const basePremium = (items: Item[]): number => {
  return groupByType(items).reduce(
    (sum, group) => sum + basePremiumForGroup(group),
    0,
  );
};

input.oldString:
const basePremiumForItem = (item: Item): number =>
  BASE_PREMIUM_BY_TYPE[item.type];

const allRunes = (items: Item[]): boolean =>
  items.every((item) => item.type === "rune");

const isRuneBlock = (items: Item[]): boolean =>
  items.length === RUNE_BLOCK_SIZE && allRunes(items);

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);

export const basePremium = (items: Item[]): number => {
  if (isRuneBlock(items)) {
    return RUNE_BLOCK_PREMIUM;
  }
  return sumOfBasePremiums(items);
};

