export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  damages: Damage[];
}

export interface Policy {
  items: Item[];
  remainingCap: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

input.newString:
const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

// The deductible is applied per damage event: each damaged item is reimbursed
// for its assessed amount minus a flat deductible.
const reimbursementFor = (damage: Damage, item: Item): number => {
  const reimbursable =
    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
      ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
      : damage.amount;
  return reimbursable - DEDUCTIBLE;
};

const findInsuredItem = (policy: Policy, itemType: string): Item =>
  policy.items.find((item) => item.type === itemType) as Item;

export const claim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = incident.damages.reduce(
    (sum, damage) =>
      sum + reimbursementFor(damage, findInsuredItem(policy, damage.itemType)),
    0,
  );
  return { payout, remainingCap: policy.remainingCap };
};

