const countByType = (things: { type?: string; itemType?: string }[], key: "type" | "itemType"): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const thing of things) {
    const t = thing[key] as string;
    counts.set(t, (counts.get(t) ?? 0) + 1);
  }
  return counts;
};

const validateDamagesCovered = (policy: Policy, incident: Incident): void => {
  const insuredCounts = countByType(policy.items, "type");
  const damageCounts = countByType(incident.damages, "itemType");
  for (const [itemType, damageCount] of damageCounts) {
    if (damageCount > (insuredCounts.get(itemType) ?? 0)) {
      throw new Error(`More ${itemType} damages than insured`);
    }
  }
};

export const claim = (policy: Policy, incident: Incident): ClaimResult => {
  validateDamagesCovered(policy, incident);
  const payout = sumBy(incident.damages, (damage) =>
    reimbursementForDamage(policy, damage),
  );
  return { payout, remainingCap: policy.remainingCap };
};

