export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

interface PolicyState {
  items: Item[];
  remainingCap: number;
}

export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
  const policies: PolicyState[] = [];
  let contractCount = 0;
  const results: StepResult[] = [];

  for (const step of scenario.steps) {
    if (step.op === "quote") {
      const customer: Customer = {
        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
        contractCount,
      };
      results.push({ premium: quote(customer, step.items) });
      policies.push({ items: step.items, remainingCap: cap(step.items) });
      contractCount += 1;
    } else {
      const policy = policies[step.policy];
      const result = claim(policy, step.incident);
      policy.remainingCap = result.remainingCap;
      results.push(result);
    }
  }

  return { results };
};

